using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "IridescentLightEffect", menuName = "Data/Battle/Effects/Austra/IridescentLight Effect")]
public class IridescentLightEffect : Effect
{
	[Header("Critical Damage")]
	[SerializeField]
	private CriticalEffect criticalEffect;

	[SerializeField]
	private int purifyPercentage;

	public int PurifyPercentage => purifyPercentage;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		text = ((amount != EffectsValues.NO_VALUE && amount != -1) ? Smart.Format(GetLocalizedDescription(), purifyPercentage, amount) : GetEffectDescriptionWithAmountReplacedWithX(GetLocalizedDescription(), purifyPercentage, GetNumberToReplaceWithX()));
		return text + AppendedDescription();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		criticalEffect.CriticalIridescentLight = true;
		return effectAmount;
	}
}
